<?php
function wc_form($action,$values=[],$file=false){echo '<form method="post" action="warranty_case_action.php"'.($file?' enctype="multipart/form-data"':'').' class="wc-form"><input type="hidden" name="csrf" value="'.e(csrf_token()).'"><input type="hidden" name="action" value="'.e($action).'">';foreach($values as $k=>$v)echo '<input type="hidden" name="'.e($k).'" value="'.e($v).'">';}
function wc_input($label,$name,$value='',$type='text',$required=true){echo '<label>'.e($label).'<input type="'.$type.'" name="'.e($name).'" value="'.e($value).'" '.($required?'required':'').' '.($type==='number'?'min="1" step="1"':'').'></label>';}
function wc_sku($label,$name,$value=''){echo '<label>'.e($label).'<input name="'.e($name).'" list="wc-products" value="'.e($value).'" placeholder="Exact Master SKU" required autocomplete="off"></label>';}
function wc_options($name,$label,$options,$selected=''){echo '<label>'.e($label).'<select name="'.e($name).'">';foreach($options as $v=>$text)echo '<option value="'.e($v).'" '.((string)$v===(string)$selected?'selected':'').'>'.e($text).'</option>';echo '</select></label>';}
function wc_ack($name,$label){echo '<label class="wc-ack"><input type="checkbox" name="'.$name.'" value="1" required> '.e($label).'</label>';}
function wc_button($text,$question=null){echo '<div class="wc-actions"><button class="btn primary"'.($question?' data-confirm="'.e($question).'"':'').'>'.e($text).'</button></div>';}
function wc_case_summary($r){$p=studio_query('SELECT name,master_sku FROM products WHERE id=?',[$r['original_product_id']])->fetch();echo '<section class="card"><div class="wc-heading"><div><h2>'.e($r['case_ref']).'</h2><p>'.e($r['claim_type']).' · '.e($r['status']).'</p></div><a class="btn ghost" href="?page=warranty_cases">All Cases</a></div><dl class="wc-summary"><div><dt>Customer / contact</dt><dd>'.e($r['customer_name'].' · '.$r['contact']).'</dd></div><div><dt>Purchase / order reference</dt><dd>'.e($r['platform'].' · '.$r['order_no']).($r['order_record_id']?' · Original order linked':' · Original Order Not in System').'</dd></div><div><dt>Original item</dt><dd>'.e($p['master_sku'].' · '.$p['name']).'</dd></div><div><dt>Claim item / quantity</dt><dd>'.e($r['claim_type']==='Component Only'?$r['component_name']:$p['name']).' · '.(int)$r['requested_qty'].' requested'.($r['approved_qty']!==null?' · '.(int)$r['approved_qty'].' approved':'').'</dd></div><div><dt>Issue</dt><dd>'.nl2br(e($r['issue'])).'</dd></div><div><dt>Receiving / replacement</dt><dd>'.e(($r['receipt_ref']?:'Not received').' / '.($r['replacement_ref']?:'Not released')).'</dd></div></dl>';if($r['evidence_path'])echo '<a class="btn ghost" target="_blank" href="warranty_case_action.php?download=evidence&amp;id='.(int)$r['id'].'">View Evidence</a>';echo '</section>';}
function wc_history($r){echo '<section class="card"><h3>Case History</h3><p>Actor, approval, exact donor unit, removed component and stock effects remain linked.</p><div class="wc-trail">';foreach(studio_query('SELECT * FROM warranty_case_events WHERE case_id=? ORDER BY id',[$r['id']]) as $ev){$d=json_decode($ev['details_json'],true)?:[];echo '<article><h4>'.e($ev['event_type']).'</h4><p class="muted">'.e($ev['created_at'].' · '.$ev['user_name'].' · '.role_label($ev['user_role'])).'</p><dl class="wc-summary">';$labels=['claim_type'=>'Claim type','original_sku'=>'Original SKU','component'=>'Component','requested_qty'=>'Requested quantity','order_match'=>'Purchase match','approved_qty'=>'Approved quantity','mode'=>'Replacement source','source_sku'=>'Source SKU','ns_source'=>'Source NS record','unit'=>'Physical unit number','component_code'=>'Component code','components_per_unit'=>'Capacity per donor unit','qty'=>'Quantity','parcel'=>'Returned parcel','linked_return_id'=>'Linked return line','non_sellable_id'=>'Non-Sellable record','donor_unit_id'=>'Donor unit','outflow_id'=>'Replacement outflow','handover_reference'=>'Tracking / handover reference','remarks'=>'Remarks'];foreach($labels as $k=>$label)if(isset($d[$k])&&$d[$k]!==''&&$d[$k]!==null)echo '<div><dt>'.e($label).'</dt><dd>'.e($d[$k]).'</dd></div>';echo '</dl>';if(isset($d['before'],$d['after'])){echo '<table class="table"><tr><th>Quantity</th><th>Before</th><th>After</th></tr>';foreach(['sellable'=>'Sellable','non_sellable'=>'Non-Sellable','physical'=>'Whole-item physical count'] as $k=>$label)echo '<tr><td>'.$label.'</td><td>'.(int)$d['before'][$k].'</td><td>'.(int)$d['after'][$k].'</td></tr>';echo '</table>';}echo '</article>';}echo '</div></section>';}
function wc_review_ui($r,$saved){if(!$saved||$saved['uid']!==current_user()['id'])throw new Exception('Review expired. Reopen the case.');$p=$saved['plan'];echo '<section class="card"><h3>Review '.($saved['mode']==='receive'?'Actual Receiving':'Replacement Release').'</h3>';if($saved['mode']==='receive'){echo '<p>'.e($p['stock_effect']).'</p><p>'.e($p['reference']).' · '.$p['qty'].' pcs</p>';}else{$s=$p['stock'];$mode=$r['source_mode'];$ds=$mode==='Sellable Whole'?-$p['units']:($mode==='Open Sellable'?-1:0);$dn=$mode==='Open Sellable'?1:0;echo '<p>'.e($p['product']['sku'].' · '.$p['product']['name']).'</p><p>'.e($p['effect']).'</p><table class="table"><tr><th>Quantity</th><th>Before</th><th>After</th></tr>';foreach(['sellable'=>'Sellable','non_sellable'=>'Non-Sellable','physical'=>'Whole-item physical count'] as $k=>$label){$delta=$k==='sellable'?$ds:($k==='non_sellable'?$dn:$ds+$dn);echo '<tr><td>'.$label.'</td><td>'.$s[$k].'</td><td>'.($s[$k]+$delta).'</td></tr>';}echo '</table>';if($p['donor'])echo '<p>Source NS-'.(int)$r['source_ns_id'].' / physical unit '.(int)$r['source_unit'].' · '.e($r['component_code']).': '.$p['donor']['used'].' already removed out of '.$p['donor']['capacity'].'.</p>';}
 wc_form($saved['mode']==='receive'?'wc_receive':'wc_release',['id'=>$r['id'],'token'=>$saved['token']]);if($saved['mode']==='release'){wc_input('Replacement tracking / handover reference','replacement_ref');echo '<label>Inspection / compatibility remarks<textarea name="inspection" required placeholder="Verified usable component, exact physical source and customer replacement"></textarea></label>';}wc_ack('physical_ack',$saved['mode']==='receive'?'I physically received this exact defective item, or verified the existing posted receipt.':'I inspected the component / whole item and verified the actual replacement handover.');wc_button('Confirm '.($saved['mode']==='receive'?'Receiving':'Replacement Release'),'Do you want to continue and post this warranty transaction?');echo '</form></section>';}
function wc_page(){if(!access_page_allowed('warranty_cases'))throw new Exception('Warranty Cases access required.');echo '<link rel="stylesheet" href="assets/warranty_cases.css?v=5.9.69"><script src="assets/warranty_cases.js" defer></script><div class="page-head"><div><h1>Warranty Cases</h1><p>CSR recording → Operations Lead approval → ICO receiving and replacement → history.</p></div>';echo '<div class="wc-actions"><a class="btn ghost" href="?page=warranty&amp;view=history">Legacy Warranty History</a>';if(can_action('wc_create'))echo '<a class="btn primary" href="?page=warranty_cases&amp;view=new">New Warranty Case</a>';echo '</div></div>';
 if(!wc_ready()){echo '<section class="card"><h3>Enable Warranty Cases</h3><p>Admin setup adds the case and component trail tables. Existing stocks and orders are preserved.</p>';if(current_user()['role']==='Admin'){wc_form('wc_setup');wc_button('Enable Warranty Cases');echo '</form>';}else echo '<p>Ask Admin to enable this feature first.</p>';echo '</section>';return;}
 echo '<datalist id="wc-products">';foreach(studio_query('SELECT master_sku,name FROM products WHERE active=1 ORDER BY name') as $p)echo '<option value="'.e($p['master_sku']).'">'.e($p['name']).'</option>';echo '</datalist><div class="wc-workspace">';$id=(int)($_GET['id']??0);
 if(($_GET['view']??'')==='new'){if(!can_action('wc_create'))throw new Exception('CSR claim recording access required.');$key=hash('sha256',random_bytes(32));$_SESSION['wc_keys'][$key]=time();$_SESSION['wc_keys']=array_slice($_SESSION['wc_keys'],-30,null,true);echo '<section class="card"><h2>Record Warranty Claim</h2><p>No stock changes when a claim is recorded.</p>';wc_form('wc_create',['request_key'=>$key],true);echo '<div class="wc-grid">';wc_options('platform','Purchase source',array_combine(array_merge(array_keys(om_shops()),['Other Purchase']),array_merge(array_keys(om_shops()),['Other Purchase'])),'Shopee');wc_input('Order ID / Booking ID / Tracking / Purchase reference','order_no');wc_sku('Original product / SKU','original_sku');wc_options('claim_type','Claim type',['Whole Part'=>'Whole Part','Component Only'=>'Component Only']);wc_input('Component name · required for component claims','component_name','','text',false);wc_input('Claim quantity','qty','1','number');wc_input('Customer name','customer_name');wc_input('Contact number','contact');echo '<label class="wc-full">Issue / complaint<textarea name="issue" required></textarea></label><label class="wc-full">Evidence · photo or PDF, optional<input type="file" name="evidence" accept="image/png,image/jpeg,application/pdf"></label></div><label class="wc-ack"><input type="checkbox" name="unrecorded_ack" value="1">If the original order is not in the system, I confirm purchase proof will be reviewed.</label>';wc_button('Submit Warranty for Review','Submit this warranty claim to Operations Lead? No stocks will change.');echo '</form></section></div>';return;}
 if(!$id){$status=is_string($_GET['status']??null)?$_GET['status']:'';$allowed=['For Review','Approved','Received','Replacement Released','Closed','Rejected'];echo '<section class="card"><div class="wc-heading"><h2>Warranty Register</h2><form method="get"><input type="hidden" name="page" value="warranty_cases"><select name="status" aria-label="Status"><option value="">All statuses</option>';foreach($allowed as $v)echo '<option '.($status===$v?'selected':'').'>'.e($v).'</option>';echo '</select><button class="btn ghost">Filter</button></form></div><div class="wc-scroll"><table class="table" data-server-paginated="1"><thead><tr><th>Reference / Date</th><th>Customer / Order</th><th>Claim</th><th>Status</th><th>Action</th></tr></thead><tbody>';$where=in_array($status,$allowed,true)?' WHERE status='.db()->quote($status):'';$total=(int)db()->query('SELECT COUNT(*) FROM warranty_cases'.$where)->fetchColumn();$offset=max(0,(int)($_GET['offset']??0));$offset=(int)(floor(min($offset,max(0,$total-1))/10)*10);foreach(db()->query('SELECT * FROM warranty_cases'.$where.' ORDER BY id DESC LIMIT 10 OFFSET '.$offset) as $r)echo '<tr><td>'.e($r['case_ref']).'<br><small>'.e($r['created_at']).'</small></td><td>'.e($r['customer_name']).'<br><small>'.e($r['platform'].' · '.$r['order_no']).'</small></td><td>'.e($r['claim_type']).'<br>'.e($r['component_name']?:'Whole part').' · '.(int)$r['requested_qty'].' pcs</td><td>'.e($r['status']).'</td><td><a class="btn ghost" href="?page=warranty_cases&amp;id='.$r['id'].'">View Case</a></td></tr>';if(!$total)echo '<tr><td colspan="5">No warranty cases yet.</td></tr>';echo '</tbody></table></div>'.rs8_pagination($total,$offset,10,['page'=>'warranty_cases','status'=>$status]).'</section>';echo '</div>';return;}
 $r=wc_case($id);wc_case_summary($r);if(($_GET['step']??'')==='review'){wc_review_ui($r,$_SESSION['wc_preview'][$id]??null);wc_history($r);echo '</div>';return;}
 if(can_action('wc_decide')&&in_array($r['status'],['For Review','Approved','Received'],true)){echo '<section class="card"><h3>Operations Lead Review</h3><p>Approval records the exact replacement source. It does not reserve or post stock.</p>';wc_form('wc_decide',['id'=>$id,'revision'=>$r['revision']]);echo '<div class="wc-grid">';wc_options('decision','Decision',['Approve'=>'Approve','Reject'=>'Reject']);wc_input('Approved quantity','approved_qty',$r['approved_qty']?:$r['requested_qty'],'number');wc_options('source_mode','Replacement source',$r['claim_type']==='Whole Part'?['Sellable Whole'=>'Sellable whole item']:['Damaged Component'=>'Component from damaged item','Open Sellable'=>'Open 1 sellable item → Incomplete / For Parts'],$r['source_mode']??'');$p=studio_query('SELECT master_sku FROM products WHERE id=?',[$r['source_product_id']?:$r['original_product_id']])->fetch();wc_sku('Source whole item / donor SKU','source_sku',$p['master_sku']);wc_options('source_platform','Sellable source platform · for sellable sources',array_combine(array_keys(om_shops()),array_keys(om_shops())),$r['source_platform']?:'Shopee');if($r['claim_type']==='Component Only'){wc_input('Stable component code · reuse for same component','component_code',$r['component_code']?:strtoupper(preg_replace('/[^A-Za-z0-9]+/','-',trim($r['component_name']))));wc_input('Components available per physical donor unit','component_capacity',$r['component_capacity']?:'1','number');echo '<label>Damaged source record · for damaged source<select name="source_ns_id"><option value="">Select damaged / for-parts record</option>';foreach(studio_query('SELECT n.*,p.master_sku FROM non_sellable n JOIN products p ON p.id=n.product_id WHERE n.qty>0 AND n.reversed_by_request IS NULL ORDER BY n.id DESC') as $n){if(studio_source($n)||(!in_array(packaging_kind($n['condition_type']),['damaged'],true)&&$n['condition_type']!=='Incomplete / For Parts'))continue;$left=(int)$n['qty']-release_total($n['id']);if($left>0)echo '<option value="'.$n['id'].'" '.((int)$r['source_ns_id']===(int)$n['id']?'selected':'').'>'.e('NS-'.$n['id'].' · '.$n['master_sku'].' · '.$left.' unit(s) · '.$n['condition_type']).'</option>';}echo '</select></label>';wc_input('Exact physical donor unit number · damaged source','source_unit',$r['source_unit']?:'1','number');}echo '<label class="wc-full">Decision / inspection requirements<textarea name="remarks" required>'.e($r['decision_notes']??'').'</textarea></label></div>';wc_ack('review_ack','I reviewed purchase proof, the exact whole part / component, quantity, compatibility and replacement source.');wc_button('Save Review Decision','Confirm this warranty decision? Approval alone does not change stocks.');echo '</form></section>';}
 if(can_action('wc_receive')&&$r['status']==='Approved'){echo '<section class="card"><h3>ICO · Actual Receiving / Link Existing Receipt</h3><p>Whole-part receiving adds only Non-Sellable. Component receiving is custody only; it never credits a whole item.</p>';wc_form('wc_receive_preview',['id'=>$id]);echo '<div class="wc-grid">';wc_input('Received date','txn_date',date('Y-m-d'),'date');wc_input('Returned parcel / tracking reference','receipt_ref');echo '<label>Existing posted damaged-return line · optional<select name="linked_return_id"><option value="">New warranty receiving</option>';if($r['claim_type']==='Whole Part')foreach(studio_query("SELECT r.id,b.batch_ref FROM posted_returns r JOIN return_batches b ON b.id=r.batch_id WHERE r.product_id=? AND r.platform=? AND r.original_ref=? AND r.damaged_qty>0 AND r.reversed=0 AND b.status='Posted'",[$r['original_product_id'],$r['platform'],$r['order_no']]) as $row)echo '<option value="'.$row['id'].'">'.e($row['batch_ref'].' · return line #'.$row['id']).'</option>';echo '</select></label></div>';wc_button('Review Actual Receiving');echo '</form></section>';}
 if(can_action('wc_release')&&$r['status']==='Received'){echo '<section class="card"><h3>ICO · Replacement</h3><p>'.e($r['source_mode']).' · approved quantity '.(int)$r['approved_qty'].'. Verify actual physical source and compatibility.</p>';wc_form('wc_release_preview',['id'=>$id]);wc_button('Review Replacement Stock Effect');echo '</form></section>';}
 if(can_action('wc_close')&&$r['status']==='Replacement Released'){echo '<section class="card"><h3>CSR · Customer Follow-up</h3>';wc_form('wc_close',['id'=>$id,'revision'=>$r['revision']]);echo '<label>Customer update / outcome<textarea name="remarks" required></textarea></label>';wc_ack('customer_ack','The customer has been informed of the replacement and tracking / handover details.');wc_button('Close Warranty Case','Close this case and preserve its full history?');echo '</form></section>';}
 if($r['donor_id']){echo '<section class="card"><h3>Donor Component Trail</h3><p>Whole-item count stays unchanged when a component is taken. An opened sellable item is held as Incomplete / For Parts.</p><table class="table"><tr><th>Source unit</th><th>Component</th><th>Capacity</th><th>Removed</th><th>Remaining</th></tr>';foreach(studio_query('SELECT d.non_sellable_id,d.unit_no,c.* FROM warranty_donor_components c JOIN warranty_donor_units d ON d.id=c.donor_id WHERE d.id=?',[$r['donor_id']]) as $d)echo '<tr><td>NS-'.$d['non_sellable_id'].' / Unit '.$d['unit_no'].'</td><td>'.e($d['component_code'].' · '.$d['component_name']).'</td><td>'.$d['capacity'].'</td><td>'.$d['used_qty'].'</td><td>'.($d['capacity']-$d['used_qty']).'</td></tr>';echo '</table></section>';}wc_history($r);echo '</div>';
}
